/**
 * Project activity event taxonomy (issue #2689, ADR-2689-01).
 *
 * Stable machine-readable event codes shared by the server recorders, the
 * validation of client-reported events and the API serializer. Presentation
 * labels are generated by the UI from these codes.
 *
 * Provenance: `server` events are performed and recorded by the server with
 * the identity of the authenticated request or socket; `client` events are
 * semantic reports from the browser that the server validates and attributes
 * to the authenticated reporter. Only `client` codes may be posted by a browser.
 *
 * Plain TypeScript: no Bun, Node or DOM APIs so it can be reused anywhere.
 */

export const SERVER_EVENT_TYPES = [
    'access.collaborator_added',
    'access.collaborator_removed',
    'access.ownership_transferred',
    'access.visibility_changed',
    'access.public_link_enabled',
    'access.public_link_disabled',
    'access.public_link_regenerated',
    'session.opened',
    'save.manual',
    'save.autosave',
    'save.unload',
    'version.restored',
] as const;

export const CLIENT_EVENT_TYPES = [
    'page.created',
    'page.renamed',
    'page.edited',
    'page.moved',
    'page.deleted',
    'page.cloned',
    'block.created',
    'block.edited',
    'block.moved',
    'block.deleted',
    'block.cloned',
    'idevice.created',
    'idevice.edited',
    'idevice.moved',
    'idevice.deleted',
    'idevice.cloned',
    'project.metadata_updated',
    'content.undone',
    'content.redone',
    'import.elpx',
    'import.elp',
    'import.idevice',
] as const;

export type ServerEventType = (typeof SERVER_EVENT_TYPES)[number];
export type ClientEventType = (typeof CLIENT_EVENT_TYPES)[number];
export type ProjectActivityEventType = ServerEventType | ClientEventType;
export type ProjectActivityProvenance = 'server' | 'client';

export const TARGET_TYPES = ['project', 'page', 'block', 'idevice', 'user'] as const;
export type ProjectActivityTargetType = (typeof TARGET_TYPES)[number];

const serverTypes: ReadonlySet<string> = new Set(SERVER_EVENT_TYPES);
const clientTypes: ReadonlySet<string> = new Set(CLIENT_EVENT_TYPES);
const targetTypes: ReadonlySet<string> = new Set(TARGET_TYPES);

export function isServerEventType(type: string): type is ServerEventType {
    return serverTypes.has(type);
}

export function isClientEventType(type: string): type is ClientEventType {
    return clientTypes.has(type);
}

export function isProjectActivityEventType(type: string): type is ProjectActivityEventType {
    return serverTypes.has(type) || clientTypes.has(type);
}

export function isTargetType(type: string): type is ProjectActivityTargetType {
    return targetTypes.has(type);
}

/** Provenance class of a stored event code; unknown codes are treated as client-reported. */
export function getEventProvenance(type: string): ProjectActivityProvenance {
    return serverTypes.has(type) ? 'server' : 'client';
}

/**
 * Limits applied to client-reported events and to every stored label.
 * Kept here so the browser reporter, the route and the tests agree.
 */
export const PROJECT_ACTIVITY_LIMITS = {
    /** Max events accepted in one POST. */
    eventsPerRequest: 100,
    /** Max request body size in bytes. */
    requestBytes: 256 * 1024,
    /** Max stored target label length (characters). */
    labelLength: 160,
    /** Max target id length. */
    targetIdLength: 64,
    /** Max session correlation id length. */
    sessionIdLength: 64,
    /** Max dedupe key length. */
    dedupeKeyLength: 96,
    /** Max serialized details size in bytes. */
    detailsBytes: 1024,
    /** Max string length inside details. */
    detailsStringLength: 160,
    /** Max aggregated count accepted per event. */
    maxCount: 100000,
    /** Oldest client timestamp accepted relative to server time (ms). */
    pastSkewMs: 24 * 60 * 60 * 1000,
    /** Furthest future client timestamp accepted relative to server time (ms). */
    futureSkewMs: 5 * 60 * 1000,
    /** Per-user sliding window for client event POSTs (per instance). */
    rateLimitRequests: 120,
    rateLimitWindowMs: 60 * 1000,
    /** Consecutive automatic saves by the same user are coalesced inside this window. */
    saveCoalesceWindowMs: 10 * 60 * 1000,
} as const;

export const TARGET_ID_PATTERN = /^[A-Za-z0-9_.:-]{1,64}$/;
export const SESSION_ID_PATTERN = /^[A-Za-z0-9_-]{8,64}$/;
export const DEDUPE_KEY_PATTERN = /^[A-Za-z0-9_:-]{1,96}$/;

/**
 * Allow-listed `details` keys per event family. Anything else is dropped
 * before storage so a client cannot smuggle content or identifiers.
 */
export const DETAIL_KEYS: Readonly<Record<string, readonly string[]>> = {
    page: ['parentId', 'fromParentId', 'toParentId', 'descendants', 'sourceId', 'keys'],
    block: ['pageId', 'pageLabel', 'fromPageId', 'toPageId', 'sourceId', 'keys'],
    idevice: ['ideviceType', 'pageId', 'pageLabel', 'blockId', 'fromBlockId', 'toBlockId', 'sourceId', 'keys'],
    project: ['keys'],
    content: ['targets'],
    import: ['format', 'mode', 'pages', 'blocks', 'components', 'assets', 'pageId'],
};

export function allowedDetailKeysFor(type: string): readonly string[] {
    const family = type.split('.')[0];
    return DETAIL_KEYS[family] ?? [];
}

// ----------------------------------------------------------------------------
// Save intent (shared with the save route and, when merged, PR #2164)
// ----------------------------------------------------------------------------

export const SAVE_KIND_HEADER = 'X-Save-Kind';
export const SAVE_KINDS = ['manual', 'collaborative-autosave', 'unload'] as const;
export type SaveKind = (typeof SAVE_KINDS)[number];

/**
 * Resolve the validated save intent of a `POST /yjs-document` request.
 * The header is client-supplied intent, not proof of a click: an absent or
 * invalid header keeps the legacy mapping (`markSaved` → manual, else unload)
 * so older bundles and `sendBeacon` posts classify the same way as before.
 */
export function resolveSaveKind(headerValue: string | null | undefined, markSaved: boolean): SaveKind {
    const normalized = (headerValue ?? '').trim().toLowerCase();
    if ((SAVE_KINDS as readonly string[]).includes(normalized)) {
        return normalized as SaveKind;
    }
    return markSaved ? 'manual' : 'unload';
}

export function saveEventTypeFor(kind: SaveKind): 'save.manual' | 'save.autosave' | 'save.unload' {
    switch (kind) {
        case 'collaborative-autosave':
            return 'save.autosave';
        case 'unload':
            return 'save.unload';
        default:
            return 'save.manual';
    }
}
